          throw new ParseError(`error: line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`error: line ${lineNumber}: candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
      continue
    }

    if (word === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 3) {
        throw new ParseError(`error: line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      if (!COUNT_RE.test(tokens[1])) {
        throw new ParseError(`error: line ${lineNumber}: count must be a positive integer`)
      }
      const count = Number(tokens[1])
      const names = []
      const seen = new Set()
      for (let j = 2; j < tokens.length; j++) {
        const name = tokens[j]
