 * `rounds` is an array of { votes, exhausted, eliminated }, one per round
 * counted, in order. `votes` is a Map from candidate name to their count
 * in that round, holding an entry for every candidate still continuing
 * at the start of that round. `eliminated` is the name removed after
 * that round, or null for the final round. `winner` is the winning name,
 * or null when no candidate ever reached a majority.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const majority = candidates.find((name) => votes.has(name) && votes.get(name) * 2 > activeTotal)
    if (majority !== undefined) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = majority
      break
    }

    const eliminated = pickElimination(continuing, votes, rounds)
    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set(continuing)
    continuing.delete(eliminated)
  }

  return { rounds, winner }
